bash -lc 
printf '%s\n' "${BASHPID}" > '/tmp/uav_usv_lab.DeRixS/experiment.pid' &&
export UAV_USV_WS='/home/qin/data/uav_usv_mpc' &&
source /opt/ros/humble/setup.bash &&
source '/home/qin/data/uav_usv_mpc/install/setup.bash' &&
cd '/home/qin/data/uav_usv_mpc' &&
ros2 launch uav_usv_bringup 'p765_perception_probe.launch.py'     enable_evaluator:=true     enable_shadow_perception:=false     front_depth_model:=ideal     enable_down_camera:=false config_file:=/home/qin/data/uav_usv_mpc/src/uav_usv_bringup/config/p76_yan_paper.yaml;
component_status=$?;
if [[ ! -f '/tmp/uav_usv_lab.DeRixS/restarting' ]]; then exec bash; fi;
exit ${component_status}
